    fn main() {
        let mut a = 2;
        let mut b = 3;
        let mut fib_numbers: Vec<i32> = Vec::new();
        fib_numbers.push(a);
        fib_numbers.push(b);

        loop {
            let next = a + b;
            if next > 20 {
                break;
            }
            fib_numbers.push(next);
            a = b;
            b = next;
        }

